import{_ as e,o as l,c as i,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-08-28","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-08-28","date":"2024-08-28T00:00:00.000Z","updated":"2024-09-04T00:00:00.000Z","tags":["Ceph","RGW","Bucket 日志","分布式存储","Ceph RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-28.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-28.md","lastUpdated":1780460162000}'),o={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-28.md"};function n(r,t,s,_,g,a){return l(),i("div",null,[...t[0]||(t[0]=[p("<p>会议纪要</p><p><strong>会议时间</strong>： 2024-08-28</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph RGW 的 Bucket 日志功能讨论</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>Bucket 日志功能介绍</strong>：</p><ul><li>会议首先介绍了 AWS 的 Bucket 日志功能，该功能允许将桶的操作（如读取、写入、设置策略等）记录到另一个桶中，形成日志。</li><li>讨论了 AWS 实现中的局限性，包括日志数量、滚动策略、写入频率、数据丢失风险等。</li></ul></li><li><p><strong>Ceph 中 Bucket 日志功能的实现</strong>：</p><ul><li>介绍了 Ceph 中 Bucket 日志功能的实现，重点在于满足备份系统的需求，包括： <ul><li>仅记录读写操作，不记录其他操作。</li><li>保证日志的持久性，避免数据丢失。</li><li>控制日志的写入频率，例如每小时写入一次。</li><li>优化日志记录格式，只记录必要信息。</li></ul></li></ul></li><li><p><strong>讨论与反馈</strong>：</p><ul><li>讨论了 Ceph 中 Bucket 日志功能的实现细节，包括： <ul><li>控制哪些操作生成日志条目。</li><li>日志的写入时机和频率。</li><li>日志的持久性和可靠性。</li><li>日志的格式和内容。</li></ul></li><li>需要进一步收集反馈，特别是针对非备份用例的具体场景。</li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>将 Bucket 日志功能的实现代码合并到 Ceph 的主分支，以便收集更多反馈。</li><li>在邮件列表和用户论坛上发布相关信息，邀请更多用户参与讨论。</li><li>根据反馈进一步完善 Bucket 日志功能。</li></ul></li></ol><p><strong>关键词</strong>： Bucket 日志、AWS、备份、持久性、可靠性、API、操作、日志格式、邮件列表、用户论坛</p><p><strong>后续行动</strong>：</p><ul><li>将代码合并到 Ceph 主分支。</li><li>发布邮件列表和用户论坛上的相关信息。</li><li>收集用户反馈。</li><li>根据反馈完善 Bucket 日志功能。</li></ul><p>[改进后的中文总结内容结束]</p>",10)])])}const d=e(o,[["render",n]]);export{c as __pageData,d as default};
